func newItemEvent() unsafe.Pointer { return unsafe.Pointer(new(billingqueue.ItemEvent)) }

func newNItemEvent(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]billingqueue.ItemEvent, n)))
}

func ptrItemEvent(p unsafe.Pointer, c int32) any {
	r := (*billingqueue.ItemEvent)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ItemID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 5:
		return &r.Text
	case 6:
		return (*string)(unsafe.Pointer(&r.ActorType))
	case 7:
		return (**string)(unsafe.Pointer(&r.ActorID))
	case 8:
		return &r.ActorName
	case 9:
		return &r.Payload
	case 10:
		return &r.At
	case 11:
		return &r.CreatedAt
	}
	return nil
}

func valueItemEvent(p unsafe.Pointer, c int32) any {
	r := (*billingqueue.ItemEvent)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ItemID)
	case 4:
		return string(r.Kind)
	case 5:
		return r.Text
	case 6:
		return string(r.ActorType)
	case 7:
		if r.ActorID == nil {
			return nil
		}
		return string(*r.ActorID)
	case 8:
		if r.ActorName == "" {
			return nil
		}
		return r.ActorName
	case 9:
		if r.Payload == nil {
			return keel.EmptyJSONObject
		}
		return r.Payload
	case 10:
		return r.At
	case 11:
		return r.CreatedAt
	}
	return nil
}

